def allpossibilities(self):
        """Returns all possible outputtemplates that may occur (recusrively applied)"""
        output = []
        for t in self.templates:
            if not isinstance(t, Template):
                output.append(t)
            else:
                output.extend(t.allpossibilities())
        return output

